-- ============================================================
-- CƠ SỞ DỮ LIỆU SQLITE TÍCH HỢP CỤC BỘ (ZERO-CONFIG FALLBACK)
-- 100% ĐỒNG BỘ DỮ LIỆU ĐẠI HỌC CÔNG NGHỆ ĐÔNG Á (EAUT)
-- ============================================================

DROP TABLE IF EXISTS chuyen_can_mon_hoc;
DROP TABLE IF EXISTS diem_danh;
DROP TABLE IF EXISTS lich_giang_day;
DROP TABLE IF EXISTS thong_bao;
DROP TABLE IF EXISTS nhat_ky_tu_van;
DROP TABLE IF EXISTS canh_bao_hoc_vu;
DROP TABLE IF EXISTS ket_qua_hoc_tap;
DROP TABLE IF EXISTS sinh_vien;
DROP TABLE IF EXISTS lop_hoc;
DROP TABLE IF EXISTS mon_hoc;
DROP TABLE IF EXISTS co_van_hoc_tap;
DROP TABLE IF EXISTS tai_khoan;

CREATE TABLE co_van_hoc_tap (
    ma_cvht TEXT PRIMARY KEY,
    ho_ten TEXT NOT NULL,
    email TEXT NOT NULL,
    so_dien_thoai TEXT,
    khoa TEXT NOT NULL
);

CREATE TABLE mon_hoc (
    ma_mon TEXT PRIMARY KEY,
    ten_mon TEXT NOT NULL,
    so_tin_chi INTEGER NOT NULL,
    so_tiet INTEGER NOT NULL,
    so_buoi_toi_da_vang INTEGER NOT NULL,
    khoa TEXT NOT NULL
);

CREATE TABLE lop_hoc (
    ma_lop TEXT PRIMARY KEY,
    ten_lop TEXT NOT NULL,
    khoa TEXT NOT NULL,
    khoa_hoc INTEGER NOT NULL,
    ma_cvht TEXT,
    FOREIGN KEY (ma_cvht) REFERENCES co_van_hoc_tap(ma_cvht) ON DELETE SET NULL
);

CREATE TABLE sinh_vien (
    ma_sv TEXT PRIMARY KEY,
    ho_ten TEXT NOT NULL,
    ngay_sinh TEXT,
    gioi_tinh TEXT,
    email TEXT,
    so_dien_thoai TEXT,
    ma_lop TEXT NOT NULL,
    trang_thai TEXT DEFAULT 'DANG_HOC',
    FOREIGN KEY (ma_lop) REFERENCES lop_hoc(ma_lop) ON DELETE CASCADE
);

CREATE TABLE ket_qua_hoc_tap (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ma_sv TEXT NOT NULL,
    hoc_ky INTEGER NOT NULL,
    nam_hoc TEXT NOT NULL,
    gpa_hoc_ky REAL NOT NULL,
    gpa_tich_luy REAL NOT NULL,
    so_tin_chi_no INTEGER DEFAULT 0,
    FOREIGN KEY (ma_sv) REFERENCES sinh_vien(ma_sv) ON DELETE CASCADE
);

CREATE TABLE canh_bao_hoc_vu (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ma_canh_bao TEXT UNIQUE NOT NULL,
    ma_sv TEXT NOT NULL,
    hoc_ky INTEGER NOT NULL,
    nam_hoc TEXT NOT NULL,
    muc_canh_bao TEXT NOT NULL,
    gpa_xet_duyet REAL NOT NULL,
    ly_do TEXT,
    ngay_quyet_dinh TEXT,
    trang_thai_tu_van TEXT DEFAULT 'CHUA_TU_VAN',
    FOREIGN KEY (ma_sv) REFERENCES sinh_vien(ma_sv) ON DELETE CASCADE
);

CREATE TABLE nhat_ky_tu_van (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ma_sv TEXT NOT NULL,
    ma_cvht TEXT NOT NULL,
    id_canh_bao INTEGER,
    ngay_tu_van TEXT NOT NULL,
    hinh_thuc TEXT NOT NULL,
    noi_dung TEXT NOT NULL,
    nguyen_nhan TEXT,
    giai_phap TEXT,
    cam_ket_sinh_vien TEXT,
    FOREIGN KEY (ma_sv) REFERENCES sinh_vien(ma_sv),
    FOREIGN KEY (ma_cvht) REFERENCES co_van_hoc_tap(ma_cvht),
    FOREIGN KEY (id_canh_bao) REFERENCES canh_bao_hoc_vu(id) ON DELETE SET NULL
);

CREATE TABLE tai_khoan (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ten_dang_nhap TEXT UNIQUE NOT NULL,
    mat_khau TEXT NOT NULL,
    ho_ten TEXT NOT NULL,
    email TEXT,
    vai_tro TEXT NOT NULL,
    ma_ref TEXT,
    trang_thai INTEGER DEFAULT 1,
    ngay_tao TEXT DEFAULT (datetime('now', 'localtime'))
);

CREATE TABLE thong_bao (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ma_thong_bao TEXT UNIQUE NOT NULL,
    tieu_de TEXT NOT NULL,
    noi_dung TEXT NOT NULL,
    nhom_rui_ro TEXT DEFAULT 'ALL',
    ma_lop TEXT DEFAULT 'ALL',
    ma_sv TEXT,
    ngay_gui TEXT DEFAULT (datetime('now', 'localtime')),
    nguoi_gui TEXT,
    so_luong_nhan INTEGER DEFAULT 0,
    trang_thai TEXT DEFAULT 'DA_GUI'
);

CREATE TABLE lich_giang_day (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ma_cvht TEXT NOT NULL,
    ten_cvht TEXT NOT NULL,
    ma_lop TEXT NOT NULL,
    ten_lop TEXT NOT NULL,
    tieu_de TEXT NOT NULL,
    ngay TEXT NOT NULL,
    gio_bat_dau TEXT NOT NULL,
    gio_ket_thuc TEXT NOT NULL,
    dia_diem TEXT NOT NULL,
    hinh_thuc TEXT NOT NULL,
    loai_buoi TEXT NOT NULL,
    trang_thai TEXT NOT NULL,
    ghi_chu TEXT
);

CREATE TABLE diem_danh (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    id_lich INTEGER NOT NULL,
    ma_sv TEXT NOT NULL,
    ngay_diem_danh TEXT NOT NULL,
    trang_thai TEXT NOT NULL,
    ghi_chu TEXT,
    FOREIGN KEY (id_lich) REFERENCES lich_giang_day(id) ON DELETE CASCADE,
    FOREIGN KEY (ma_sv) REFERENCES sinh_vien(ma_sv) ON DELETE CASCADE
);

CREATE TABLE chuyen_can_mon_hoc (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ma_sv TEXT NOT NULL,
    ma_lop TEXT NOT NULL,
    ma_mon TEXT NOT NULL,
    hoc_ky INTEGER NOT NULL,
    nam_hoc TEXT NOT NULL,
    tong_so_buoi INTEGER NOT NULL,
    so_buoi_co_mat INTEGER NOT NULL,
    so_buoi_muon INTEGER NOT NULL,
    so_buoi_vang_co_phep INTEGER NOT NULL,
    so_buoi_vang_khong_phep INTEGER NOT NULL,
    tong_buoi_vang_quy_doi REAL NOT NULL,
    ty_le_vang REAL NOT NULL,
    diem_chuyen_can REAL NOT NULL,
    trang_thai_du_thi TEXT NOT NULL,
    ly_do_cam_thi TEXT,
    FOREIGN KEY (ma_sv) REFERENCES sinh_vien(ma_sv) ON DELETE CASCADE,
    FOREIGN KEY (ma_mon) REFERENCES mon_hoc(ma_mon) ON DELETE CASCADE
);

